/* Picasso Intelligence — store data.
   Titles and prices come from store.cubemars.com/products.json.
   Verify every price before launch — they move. */

window.SITE = {
  brand: "Picasso Intelligence",
  tagline: "",
  /* The strip at the top of every page, rendered by renderChrome, so this list
     is the whole site's banner. "No Tariffs" is the trade's shorthand for DDP
     and what a competitor selling the same parts runs; the tariff is real and
     we pay it, and the buyer pays nothing on delivery. It holds for US orders.
     International orders are quoted per country with duty itemised, which the
     FAQ and the shipping policy say - the banner has no room to. */
  announce: ["US-based team", "No Tariffs", "Engineering support before and after you buy"],
  /* No phone number on the site by choice — enquiries come in by email so
     they arrive with the model and quantity written down. */
  email: "info@picassointelligence.com",
  /* Formspree relays the contact form. The endpoint is public by design — it
     ships in the page source — and the destination inbox is set in Formspree,
     never here. Free tier is 50 submissions a month. */
  formEndpoint: "https://formspree.io/f/xoeqdwez",
  /* Cloudflare Worker that creates the Stripe Checkout Session. Prices are
     resolved there, never here, so a tampered cart cannot set its own total.
     Empty until the worker is deployed — the cart falls back to the email flow. */
  checkoutEndpoint: "https://checkout.picasso-intelligence.workers.dev/",
  /* PayPal, taken directly rather than through Stripe: Stripe process PayPal
     only for businesses in 29 European countries, and this one is in New York.
     Venmo rides on the same integration -- one parameter on the SDK -- so it
     appears for US buyers who have the app, at no extra work.

     This id is public: it names the merchant to PayPal and ships in the page.
     The secret is a Cloudflare secret, PAYPAL_CLIENT_SECRET, and is not in
     this repository. Empty here means no PayPal button renders at all. */
  paypalClientId: "",
  /* Our price is the CubeMars online price × 1.12. Change a price here and
     nowhere else: tools/build-static.py regenerates the product pages, the
     sitemap, worker/prices.json and worker/checkout.bundled.js from this file.
     The Cloudflare worker is what Stripe actually charges, and it only picks
     up a change when checkout.bundled.js is pasted into the dashboard. */

  /* Above this order value the cart stops offering online payment and sends
     the buyer to a quote instead, because an order this size deserves the
     volume price from the supplier and freight worked out by a person. The
     worker enforces it too; the button alone is only a suggestion. */
  selfServeMax: 5000,

  /* Published volume discounts, off the list price of the goods. Nothing here
     is applied by code: an order this size is quoted rather than paid online,
     so these are the numbers a person quotes from. They are printed anyway,
     because a buyer sizing up a fleet order should be able to see the break
     before deciding whether it is worth asking.
     The FAQ answer and the "Request Volume Quote" card further down repeat
     these in prose. Change all three together. */
  volumeTiers: [
    { from: 5000,  off: 3 },
    { from: 10000, off: 5 },
    { from: 25000, off: 8 }
  ],
  /* Freight zones, charged once per order. This array is the ONE source of
     truth: tools/build-static.py copies it verbatim into the worker, so what
     the cart shows and what Stripe charges cannot drift apart. Keys are quoted
     because the generator parses this block as JSON.

     rates    bands in ascending order; the first band whose `upTo` the
              subtotal has not reached wins. The last band must have
              "upTo": null so there is always a match.
     dutyPaid true where we pay the import duty (DDP). Only the US today —
              elsewhere duty varies far too much by destination.

     To open a country: add a zone with real freight numbers, e.g.
       { "code": "CA", "name": "Canada", "countries": ["CA"], "dutyPaid": false,
         "rates": [{ "upTo": 1500, "cost": 90 }, { "upTo": null, "cost": 0 }] }
     A second zone makes a "Ship to" selector appear in the cart by itself. */
  shippingZones: [
    { "code": "US", "name": "United States", "countries": ["US"], "dutyPaid": true,
      "rates": [{ "upTo": 200, "cost": 10 }, { "upTo": null, "cost": 0 }] }
  ],
  address: "215 W 125th St, New York, NY 10027",
  location: "New York",
  linkedin: "#",
  year: 2026,
  /* $ threshold above which ACH is promoted as the cheaper option */
  achThreshold: 1000
};

